    stock_price = 150.0
    strike_price = 160.0
    time_to_expiration = 6 / 12  # Convert 6 months to years
    risk_free_rate = 5 / 100    # Convert 5% to decimal
    volatility = 20 / 100       # Convert 20% to decimal
    option_type = 'call'

    # Custom norm_cdf function using math.erf as scipy.stats is not allowed
    def norm_cdf(x):
        return 0.5 * (1 + math.erf(x / math.sqrt(2)))

    d1 = (math.log(stock_price / strike_price) + (risk_free_rate + 0.5 * volatility ** 2) * time_to_expiration) / (volatility * math.sqrt(time_to_expiration))
    d2 = d1 - volatility * math.sqrt(time_to_expiration)

    if option_type == 'call':
        option_price = (stock_price * norm_cdf(d1)) - (strike_price * math.exp(-risk_free_rate * time_to_expiration) * norm_cdf(d2))
    elif option_type == 'put':
        option_price = (strike_price * math.exp(-risk_free_rate * time_to_expiration) * norm_cdf(-d2)) - (stock_price * norm_cdf(-d1))
    else:
        raise ValueError("Option type must be either 'call' or 'put'.")

    return round(option_price, 2)

